 void addCategoryChip(String key,String label){TextView chip=text(label,13,0xFFD1DAEB);chip.setSingleLine();chip.setGravity(Gravity.CENTER);chip.setPadding(dp(16),0,dp(16),0);chip.setMinWidth(dp(64));chip.setTypeface(null,Typeface.BOLD);int accent=DrawerSectionView.accent(key);StateListDrawable state=new StateListDrawable();GradientDrawable selected=bg(accent,22),normal=bg(0xFF242E40,22);normal.setStroke(dp(1),0x443F4F68);state.addState(new int[]{android.R.attr.state_selected},selected);state.addState(new int[]{},normal);android.content.res.ColorStateList ink=new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_selected},new int[]{}},new int[]{0xFF111923,0xFFD1DAEB});chip.setTextColor(ink);chip.setBackground(new InsetDrawable(new RippleDrawable(android.content.res.ColorStateList.valueOf(0x44FFFFFF),state,null),0,dp(4),0,dp(4)));chip.setContentDescription(getString(R.string.drawer_jump_to,label));chip.setOnClickListener(v->jumpToCategory(key));LinearLayout.LayoutParams size=new LinearLayout.LayoutParams(-2,dp(48));size.rightMargin=dp(6);categoryChipContainer.addView(chip,size);categoryChips.put(key,chip);}
