 void updateDrawerLayout(boolean browsing,boolean reset){
  if(drawerHorizontalArea==null)return;boolean horizontal=drawerOrientation==1&&browsing;
  drawerList.setVisibility(horizontal?View.GONE:View.VISIBLE);drawerHorizontalArea.setVisibility(horizontal?View.VISIBLE:View.GONE);
  if(horizontal){drawerCellHeight=Math.max(100,iconSize()+42);drawerPageRows=Math.max(1,(drawerPager.getHeight()-dp(64))/dp(drawerCellHeight));rebuildDrawerPages(reset);}
 }
 void rebuildDrawerPages(boolean reset){
  String key=!reset&&!drawerPages.isEmpty()?drawerPages.get(Math.min(drawerPage,drawerPages.size()-1)).key:"";
  int part=!reset&&!drawerPages.isEmpty()?drawerPages.get(Math.min(drawerPage,drawerPages.size()-1)).part:0;
  drawerPages.clear();drawerPages.addAll(DrawerPages.build(drawerSections,drawerPageRows*4));
  int first=DrawerPages.firstPage(drawerPages,key);drawerPage=first<0?0:first+Math.min(part,drawerPages.get(first).parts-1);
  drawerPager.refresh(drawerPage);updateDrawerPageLabel();
 }
 View createDrawerPage(int position){
  DrawerPages.Page<App> page=drawerPages.get(position);LinearLayout content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);
  DrawerSectionView header=new DrawerSectionView(this);header.bind(page.key,drawerSectionTitle(page.key),page.total,false,true);content.addView(header,new LinearLayout.LayoutParams(-1,dp(64)));
  for(int start=0;start<page.apps.size();start+=4){LinearLayout row=new LinearLayout(this);DrawerSectionView.Wash wash=new DrawerSectionView.Wash();wash.bind(page.key);row.setBackground(wash);
   for(int col=0;col<4;col++){int index=start+col;if(index>=page.apps.size()){row.addView(new View(this),new LinearLayout.LayoutParams(0,-1,1));continue;}
    App app=page.apps.get(index);LinearLayout cell=appCell(app,true,0xFFE6E9F2);cell.setOnClickListener(v->launch(app,v));cell.setOnLongClickListener(v->{startDrawerDrag(v,app);return true;});row.addView(cell,new LinearLayout.LayoutParams(0,-1,1));
   }content.addView(row,new LinearLayout.LayoutParams(-1,dp(drawerCellHeight)));
  }return content;
 }
 void updateDrawerPageLabel(){
  if(drawerPageLabel==null||!horizontalDrawerVisible())return;
  if(drawerPages.isEmpty()){drawerPageLabel.setText(getString(R.string.ui_026));drawerPrevious.setEnabled(false);drawerNext.setEnabled(false);return;}
  drawerPage=Math.max(0,Math.min(drawerPage,drawerPages.size()-1));DrawerPages.Page<App> page=drawerPages.get(drawerPage);
  String name=drawerSectionTitle(page.key);drawerPageLabel.setText(getString(R.string.drawer_page_label,name,page.part+1,page.parts,drawerPage+1,drawerPages.size()));drawerPageLabel.setContentDescription(getString(R.string.drawer_page_accessibility,name,page.part+1,page.parts,drawerPage+1,drawerPages.size()));
  drawerPrevious.setEnabled(drawerPage>0);drawerNext.setEnabled(drawerPage<drawerPages.size()-1);drawerPrevious.setAlpha(drawerPage>0?1:.3f);drawerNext.setAlpha(drawerPage<drawerPages.size()-1?1:.3f);selectCategoryChip(page.key.equals("frequent")||page.key.equals("other-apps")?"all":page.key,true);
 }
 boolean sectionCollapsed(String key){return !key.equals("search")&&prefs.getBoolean("drawerCollapsed:"+key,false);}
 void toggleDrawerSection(String key){
  if(drawerList==null||key.equals("search"))return;
  int first=drawerList.getFirstVisiblePosition();View firstView=drawerList.getChildAt(0);
  int top=firstView==null?0:firstView.getTop();String anchor=first<drawerRows.size()?drawerRows.get(first).key:key;
  int offset=first-drawerSectionPositions.getOrDefault(anchor,first);
  boolean expand=sectionCollapsed(key);prefs.edit().putBoolean("drawerCollapsed:"+key,!expand).apply();
  fillDrawer(query.getText().toString());
  int position=drawerSectionPositions.getOrDefault(anchor,0)+(anchor.equals(key)?0:offset);
  drawerList.setSelectionFromTop(Math.min(position,Math.max(0,drawerRows.size()-1)),top);
  if(expand&&android.animation.ValueAnimator.areAnimatorsEnabled())drawerList.post(()->{
   for(int n=0;n<drawerList.getChildCount();n++){int row=drawerList.getFirstVisiblePosition()+n;
    if(row<drawerRows.size()&&drawerRows.get(row).heading==null&&drawerRows.get(row).key.equals(key)){
     View child=drawerList.getChildAt(n);child.setAlpha(.35f);child.setTranslationY(-dp(8));child.animate().alpha(1).translationY(0).setDuration(180).start();
    }
   }
  });
 }
