 void startWidgetPlacement(int id){if(widgetManager.getAppWidgetInfo(id)==null)return;dismissHomePopup();closeDrawerImmediately();if(editToolbar!=null){root.removeView(editToolbar);editToolbar=null;}placingWidget=true;editingHome=true;placementId=id;placementPage=id==prefs.getInt("widget",-1)?Math.min(model.pages.size()-1,prefs.getInt("widgetPage",0)):model.currentPage;model.currentPage=placementPage;placementGeometry=id==prefs.getInt("widget",-1)?readWidgetGeometry():new WidgetGeometry(.05f,.1f,.8f,.25f);prefs.edit().putInt("pendingPlacement",id).apply();homeContent.setPadding(0,dp(12),0,dp(appliedSearchGap));renderSlots();showPlacementToolbar();root.post(()->{if(placementBoard!=null)placementBoard.findSpace();});}
 void showPlacementToolbar(){if(editToolbar!=null)root.removeView(editToolbar);LinearLayout bar=new LinearLayout(this);bar.setOrientation(LinearLayout.VERTICAL);bar.setPadding(dp(8),dp(4),dp(8),dp(4));bar.setBackground(bg(0xF0232D40,18));placementStatus=text(getString(R.string.ui_062),12,Color.WHITE);LinearLayout heading=new LinearLayout(this);heading.setGravity(Gravity.CENTER_VERTICAL);heading.addView(placementStatus,new LinearLayout.LayoutParams(0,dp(48),1));if(placementId==prefs.getInt("widget",-1)){TextView remove=text(getString(R.string.ui_061),12,0xFFFFB4B4);remove.setContentDescription(getString(R.string.ui_061));heading.addView(remove,new LinearLayout.LayoutParams(dp(86),dp(48)));remove.setOnClickListener(v->removeHomeWidget());}bar.addView(heading);LinearLayout actions=new LinearLayout(this);String[] names={"‹","›",getString(R.string.ui_140),getString(R.string.ui_063),getString(R.string.ui_064)};for(int n=0;n<names.length;n++){final int action=n;TextView button=text(names[n],15,0xFFD7E3FF);button.setContentDescription(names[n]);actions.addView(button,new LinearLayout.LayoutParams(0,dp(48),1));button.setOnClickListener(v->{if(action==3){cancelPlacement();return;}if(action==4){commitPlacement();return;}if(action==2){model.currentPage=model.addPage();}else model.currentPage=Math.max(0,Math.min(model.pages.size()-1,model.currentPage+(action==0?-1:1)));placementPage=model.currentPage;save();renderSlots();});}bar.addView(actions);FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(-1,dp(108),Gravity.BOTTOM);lp.setMargins(dp(12),dp(4),dp(12),0);editToolbar=bar;root.addView(bar,lp);}
 void placementValidity(boolean valid){if(placementStatus!=null){placementStatus.setText(valid?getString(R.string.ui_062):getString(R.string.ui_065));placementStatus.setTextColor(valid?Color.WHITE:0xFFFFAAAA);}}
 void commitPlacement(){if(placementBoard==null||!placementBoard.valid()){Toast.makeText(this,getString(R.string.ui_066),Toast.LENGTH_SHORT).show();return;}placementBoard.updateSize();int old=prefs.getInt("widget",-1);prefs.edit().putInt("widget",placementId).putInt("widgetPage",placementPage).putFloat("widgetX",placementGeometry.x).putFloat("widgetY",placementGeometry.y).putFloat("widgetWidth",placementGeometry.width).putFloat("widgetHeightFraction",placementGeometry.height).remove("pendingPlacement").apply();if(old!=-1&&old!=placementId)widgetHost.deleteAppWidgetId(old);endPlacement();}
 void cancelPlacement(){int old=prefs.getInt("widget",-1);if(placementId!=-1&&placementId!=old)widgetHost.deleteAppWidgetId(placementId);prefs.edit().remove("pendingPlacement").apply();endPlacement();}
 void endPlacement(){placingWidget=false;editingHome=false;placementBoard=null;placementStatus=null;placementId=-1;if(editToolbar!=null){root.removeView(editToolbar);editToolbar=null;}homeContent.setPadding(0,dp(12),0,dp(appliedSearchGap));renderSlots();save();}
 void removeHomeWidget(){cancelUnlockEntrance();int id=prefs.getInt("widget",-1),candidate=prefs.getInt("pendingPlacement",-1);android.content.SharedPreferences.Editor edit=prefs.edit();for(String key:new String[]{"widget","widgetPage","widgetX","widgetY","widgetWidth","widgetHeightFraction","widgetHeight","widgetReserved","pendingPlacement"})edit.remove(key);edit.apply();placingWidget=false;editingHome=false;placementId=-1;pendingWidget=-1;placementBoard=null;visibleWidgetBoard=null;placementStatus=null;editToolbar=null;for(int removed:new int[]{id,candidate})if(removed!=-1&&(removed==id||candidate!=id)){try{widgetHost.deleteAppWidgetId(removed);}catch(IllegalArgumentException ignored){/* Already removed by Android/provider: keep local cleanup. */}if(candidate==id)break;}build();Toast.makeText(this,getString(R.string.widget_removed),Toast.LENGTH_SHORT).show();}
 void excludeLauncherTasksFromRecents(){
  // Manifest covers new tasks. Update old roots off the UI thread on upgrade/startup.
  appWorker.execute(()->{
   for(ActivityManager.AppTask task:getSystemService(ActivityManager.class).getAppTasks()){
    try{task.setExcludeFromRecents(true);}catch(IllegalArgumentException|SecurityException e){android.util.Log.w("PixelAirTasks","Could not update a launcher task",e);}
   }
  });
 }
 void registerUnlockEvents(){unlockReceiver=new BroadcastReceiver(){@Override public void onReceive(Context context,Intent intent){String action=intent.getAction();if(Intent.ACTION_SCREEN_OFF.equals(action)){unlockGate.screenOff(homeResumed||unlockGate.isArmed());removeUnlockPreDraw();if(unlockGate.isArmed())prepareUnlockEntrance();else cancelUnlockEntrance();}else if(Intent.ACTION_USER_PRESENT.equals(action)){unlockGate.unlocked(SystemClock.elapsedRealtime());tryUnlockEntrance();}else if(Intent.ACTION_SCREEN_ON.equals(action)){if(!getSystemService(KeyguardManager.class).isKeyguardLocked()){unlockGate.unlocked(SystemClock.elapsedRealtime());tryUnlockEntrance();}}}};IntentFilter filter=new IntentFilter();filter.addAction(Intent.ACTION_SCREEN_OFF);filter.addAction(Intent.ACTION_SCREEN_ON);filter.addAction(Intent.ACTION_USER_PRESENT);registerReceiver(unlockReceiver,filter,Context.RECEIVER_NOT_EXPORTED);}
 void collectEntranceCells(View view,ArrayList<View> cells){Object address=view.getTag(R.id.workspace_address);if(address instanceof Integer){int slot=(Integer)address;if((slot<0||slot/20==model.currentPage)&&"occupied".equals(view.getTag()))cells.add(view);return;}if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int n=0;n<group.getChildCount();n++)collectEntranceCells(group.getChildAt(n),cells);}}
 void prepareUnlockEntrance(){if(root==null||drawer!=null||editingHome||!prefs.getBoolean("unlockAnimation",true)||!android.animation.ValueAnimator.areAnimatorsEnabled()){cancelUnlockEntrance();return;}ArrayList<View> cells=new ArrayList<>();collectEntranceCells(home,cells);unlockAnimator.prepare(cells);}
 void removeUnlockPreDraw(){if(unlockPreDraw!=null&&unlockPreDrawRoot!=null&&unlockPreDrawRoot.getViewTreeObserver().isAlive())unlockPreDrawRoot.getViewTreeObserver().removeOnPreDrawListener(unlockPreDraw);unlockPreDraw=null;unlockPreDrawRoot=null;}
 void cancelUnlockEntrance(){removeUnlockPreDraw();unlockAnimator.cancel();}
 boolean unlockHomeReady(){return !destroyed&&homeResumed&&hasWindowFocus()&&root!=null&&getSystemService(PowerManager.class).isInteractive()&&!getSystemService(KeyguardManager.class).isKeyguardLocked();}
 void tryUnlockEntrance(){if(!unlockHomeReady())return;if(unlockPreDraw!=null)return;if(unlockGate.isArmed())unlockGate.unlocked(SystemClock.elapsedRealtime());if(!unlockGate.hasPending(SystemClock.elapsedRealtime())){if(unlockAnimator.isPrepared())cancelUnlockEntrance();return;}prepareUnlockEntrance();if(!unlockAnimator.isPrepared())return;unlockPreDrawRoot=root;unlockPreDraw=()->{removeUnlockPreDraw();if(unlockHomeReady()&&drawer==null&&!editingHome&&unlockGate.take(SystemClock.elapsedRealtime(),true)){int style=prefs.getInt("unlockStyle",0);unlockAnimator.startPrepared(root,style);android.util.Log.d("PixelAirUnlock","Home entrance staged before first draw, style="+style);}else if(unlockHomeReady()&&!unlockGate.hasPending(SystemClock.elapsedRealtime()))cancelUnlockEntrance();return true;};root.getViewTreeObserver().addOnPreDrawListener(unlockPreDraw);root.invalidate();}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused){tryUnlockEntrance();handler.postDelayed(()->{if(!destroyed)tryUnlockEntrance();},120);}}
 @Override protected void onPause(){if(getSystemService(KeyguardManager.class).isKeyguardLocked()||!getSystemService(PowerManager.class).isInteractive()){unlockGate.homeBehindKeyguard();removeUnlockPreDraw();prepareUnlockEntrance();}else{unlockGate.leaveHome();cancelUnlockEntrance();}homeResumed=false;super.onPause();}
 void finishWidget(int id,boolean configure){AppWidgetProviderInfo info=widgetManager.getAppWidgetInfo(id);if(info==null){widgetHost.deleteAppWidgetId(id);pendingWidget=-1;return;}if(configure&&info.configure!=null){try{widgetHost.startAppWidgetConfigureActivityForResult(this,id,0,21,null);}catch(Exception e){widgetHost.deleteAppWidgetId(id);pendingWidget=-1;Toast.makeText(this,getString(R.string.ui_067),Toast.LENGTH_SHORT).show();}return;}pendingWidget=-1;startWidgetPlacement(id);}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==40){applyLauncherPreferences();if(result==RESULT_OK&&data!=null)settingsAction(data.getStringExtra("action"));return;}if(req!=22&&req!=21)return;int id=data!=null?data.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,pendingWidget):pendingWidget;if(result!=RESULT_OK){if(id!=-1)widgetHost.deleteAppWidgetId(id);pendingWidget=-1;return;}finishWidget(id,req==22);}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putInt("pendingWidget",pendingWidget);}
 @Override protected void onRestoreInstanceState(Bundle b){super.onRestoreInstanceState(b);pendingWidget=b.getInt("pendingWidget",-1);}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);closeDrawerImmediately();if(Intent.ACTION_MAIN.equals(i.getAction())&&i.hasCategory(Intent.CATEGORY_HOME)&&!stoppedSinceResume&&model.currentPage!=0)pageContainer.selectPage(0);}
 @Override protected void onStart(){super.onStart();widgetHost.startListening();}
 @Override protected void onResume(){super.onResume();homeResumed=true;stoppedSinceResume=false;applyLauncherPreferences();if(getSystemService(KeyguardManager.class).isKeyguardLocked()||!getSystemService(PowerManager.class).isInteractive()){unlockGate.homeBehindKeyguard();prepareUnlockEntrance();}else if(unlockGate.isArmed()&&!unlockAnimator.isPrepared())prepareUnlockEntrance();if(date!=null)updateDate();tryUnlockEntrance();handler.postDelayed(()->{if(!destroyed){updateDrawerOrder();ensureDrawerCached();}},250);}
 @Override protected void onStop(){super.onStop();stoppedSinceResume=true;drawerDragId=null;applyWindowBlur(0);dismissHomePopup();widgetHost.stopListening();handler.removeCallbacks(tick);}
 @Override protected void onDestroy(){destroyed=true;cancelUnlockEntrance();if(unlockReceiver!=null)unregisterReceiver(unlockReceiver);if(blurListener!=null)getWindowManager().removeCrossWindowBlurEnabledListener(blurListener);if(packageReceiver!=null)unregisterReceiver(packageReceiver);appWorker.shutdownNow();dismissHomePopup();handler.removeCallbacksAndMessages(null);super.onDestroy();}

